insert into public.chapters (chapter, title, scenarios) values (1, 'Managing Today: The Real Talk on Bossing Up', '{"The Busy Day": "Don Sakaguchi, manager at Control Systems, Inc., sighs as he sips his coffee at 5 A.M. and reads his agenda for the day. Don''s first duty is to preside over a retirement party for a beloved employee and say a few words on her behalf. Next, he will give a tour to a news reporter who is writing a story on the new plant expansion. Don then has a meeting with the unit manager, Phil Johnson, to discuss Phil''s recent performance drop (a task Don always hates). Finally, in the late afternoon, Don will be reviewing the recent equipment malfunction and deciding whether to deploy extra people to get the equipment running as soon as possible. What a day!", "The General Manager": "Michelle is the general manager of a power plant. This morning, she will meet with city officials to discuss environmental issues. After the meeting, she will confer with the plant''s section managers to address the concerns of the city representatives. This afternoon, Michelle will meet with a team leader to go over a complaint filed by an employee. After the complaint meeting, Michelle plans to spend time in the library and on the Internet researching new technologies that can be used to improve the performance of her plant.", "The Perfect Manager": "Brenda Kraft has proven herself to be an able manager. Her section has a high project completion rate with the highest-quality product and the lowest defects in her division. In addition, she accomplishes this with fewer full-time people than other managers. Coworkers say that the secret of her success is in her ability to determine what needs to be done and by whom, and her understanding of the basic \"management processes.\""}'::jsonb) on conflict (chapter) do update set title = excluded.title, scenarios = excluded.scenarios;
insert into public.questions (id, chapter, num, scenario, question, options, answer, marked, note) values
('c1-q01', 1, 1, null, 'The work of a manager ________.', '["is strictly limited to overseeing and monitoring the work of others", "may involve performing tasks that are not related to overseeing others", "involves only high-level tasks that require a sophisticated skill set", "does not involve interaction with nonmanagerial employees"]'::jsonb, 'B', 'B', null),
('c1-q02', 1, 2, null, 'Which one of the following did Taylor NOT find appalling in his study of workers in steel companies?', '["Workers \"took it easy\" on the job.", "Workers employed different techniques for the same job.", "Workers would only attempt to perform a job if they were shown to have aptitude for it.", "Worker output was only about one-third of what was possible."]'::jsonb, 'C', 'C', null),
('c1-q03', 1, 3, null, 'Which one of the following might be an example of increased efficiency in manufacturing?', '["cutting the amount of labor required to make the product", "cutting the price of the product", "increasing sales of the product", "increasing advertising for the product"]'::jsonb, 'A', null, 'Not marked on the sheet. Efficiency = getting more output from fewer inputs (labor is an input).'),
('c1-q04', 1, 4, null, 'A candy manufacturer would increase both efficiency and effectiveness by making ________.', '["better candy at the same cost", "better candy at a lower cost", "the same candy at a lower cost", "the same candy at the same cost"]'::jsonb, 'B', null, 'Not marked on the sheet. Better candy = effectiveness (goal attainment), lower cost = efficiency (fewer resources).'),
('c1-q05', 1, 5, null, 'A candy manufacturer that made candy at a lower cost without improving the quality of the candy could be said to ________.', '["increase effectiveness without increasing efficiency", "increase efficiency without increasing effectiveness", "increase both effectiveness and efficiency", "decrease both effectiveness and efficiency"]'::jsonb, 'B', 'B', null),
('c1-q06', 1, 6, null, 'Giving a speech at an organization banquet would fall into which Mintzberg category?', '["informational", "interpersonal", "decisional", "entrepreneurial"]'::jsonb, 'B', null, 'Not marked on the sheet. Ceremonial duties = figurehead role, which belongs to the interpersonal category.'),
('c1-q07', 1, 7, 'The Busy Day', 'When Don attends the retirement party, he will be operating in which of the management roles?', '["leader", "liaison", "monitor", "figurehead"]'::jsonb, 'D', 'D', null),
('c1-q08', 1, 8, 'The Busy Day', 'When Don meets with Phil to discuss Phil''s output decline, in which management role will Don be operating?', '["leader", "figurehead", "disseminator", "spokesperson"]'::jsonb, 'A', 'A', null),
('c1-q09', 1, 9, 'The Busy Day', 'What kind of a manager is Don likely to be?', '["first-line manager", "CEO of a major corporation", "low-level middle manager", "plant manager"]'::jsonb, 'D', 'D', null),
('c1-q10', 1, 10, 'The General Manager', 'When Michelle learns from city officials about how her plant''s operations may be affecting the environment, she is performing which management role?', '["leader", "resource allocator", "entrepreneur", "liaison"]'::jsonb, 'D', 'D', 'On the sheet both B and D look partly circled; D (liaison = contact with outsiders) is correct.'),
('c1-q11', 1, 11, 'The General Manager', 'When Michelle spends time searching for new technologies for her plant, she is performing which management role?', '["leader", "entrepreneur", "spokesperson", "disturbance handler"]'::jsonb, 'B', 'B', null),
('c1-q12', 1, 12, null, 'Who stands to benefit least from studying management?', '["a pro football coach", "a pro football spectator", "a pro football owner", "a pro football player"]'::jsonb, 'B', 'B', null),
('c1-q13', 1, 13, null, 'A common factor that all managers face in today''s world is the ________.', '["changing nature of work", "lagging development of technology", "demand to move to a production based economy", "boredom of employees"]'::jsonb, 'A', 'A', null),
('c1-q14', 1, 14, null, 'A college Spanish club is an example of an organization because it is comprised of people who ________.', '["share the same values, traditions, and customs", "share the same goals and values", "share goals and function within a common structure", "function under the same set of rules and regulations"]'::jsonb, 'C', 'C', null),
('c1-q15', 1, 15, null, 'Which one of the following is an important job responsibility for a middle manager?', '["defining the organization''s long-term goals", "translating goals defined by top managers into action", "helping top managers define goals", "performing tasks that are not related to long-term goals"]'::jsonb, 'B', 'B', null),
('c1-q16', 1, 16, null, 'Of the following, which one is the lowest level of management?', '["a nonmanagerial employee", "an individual involved in defining the organization''s philosophy", "a vice president", "a middle manager"]'::jsonb, 'D', 'D', null),
('c1-q17', 1, 17, null, 'An organization is ________.', '["the physical location where people work", "any collection of people who perform similar tasks", "a deliberate arrangement of people to accomplish some specific purpose", "a group of individuals focused on profit-making for their shareholders"]'::jsonb, 'C', 'C', null),
('c1-q18', 1, 18, null, 'A major contribution that Taylor made to the study of management was ________.', '["to measure efficiency on a 4-star scale", "to identify the one best way to get a job done", "to identify the three best ways to get a job done", "to measure inefficiency on a 4-star scale"]'::jsonb, 'B', 'B', null),
('c1-q19', 1, 19, 'The Perfect Manager', 'Brenda''s high project completion rate indicates that she is ________.', '["an efficient manager", "an effective manager", "a good spokesperson", "a good resource allocator"]'::jsonb, 'B', 'B', null),
('c1-q20', 1, 20, 'The Perfect Manager', 'If Brenda accomplished her projects with high-quality results, but she took more time than other managers in the process, you could say that as a manager she was ________.', '["efficient, but not effective", "a leader, but not a top manager", "project oriented, but not effective", "effective, but not efficient"]'::jsonb, 'D', 'D', null),
('c1-q21', 1, 21, null, 'Efficiency refers to ________.', '["the relationship between inputs and outputs", "the additive relationship between inputs and outputs", "the inverse relationship between inputs and outputs", "decreasing inputs only"]'::jsonb, 'A', 'A', null),
('c1-q22', 1, 22, 'The Perfect Manager', 'Brenda''s ability to determine what needs to be done and by whom is evidence that she excels at which management function?', '["planning", "controlling", "leading", "organizing"]'::jsonb, 'D', 'D', 'B is underlined on the sheet, D is circled. Organizing = determining what needs to be done, how and by whom.'),
('c1-q23', 1, 23, null, 'Today, the basic management functions are considered to be ________.', '["planning, coordinating, leading, and monitoring", "planning, organizing, leading, and motivating", "commanding, organizing, leading, and decision making", "planning, organizing, leading, and controlling"]'::jsonb, 'D', 'D', null),
('c1-q24', 1, 24, null, 'Which one of the following is NOT considered part of the planning function?', '["defining goals", "motivating", "mapping out strategy", "making decisions"]'::jsonb, 'B', 'B', 'The end of the question is cut off in the scan ("…NOT consider…"). Wording completed from the textbook test bank – please check against your printout.'),
('c1-q25', 1, 25, null, 'Mintzberg developed his 10 managerial roles by ________.', '["sending out questionnaires to thousands of managers", "observing hundreds of managers over several years", "closely monitoring the work activities of five chief executives", "using common sense to analyze the situation"]'::jsonb, 'C', 'C', null),
('c1-q26', 1, 26, null, 'A pharmaceutical company manager attending a meeting of academic scientists would be functioning in which role?', '["informational", "figurehead", "liaison", "decisional"]'::jsonb, 'C', 'C', null),
('c1-q27', 1, 27, null, 'The emphasis that managers give to various activities is generally based on their ________.', '["organizational level", "tenure with the organization", "experience in their field", "skill specialty"]'::jsonb, 'A', 'A', null),
('c1-q28', 1, 28, null, 'One managerial function that is identical in both Fayol''s and Mintzberg''s systems is ________.', '["leader", "resource allocator", "monitor", "negotiator"]'::jsonb, 'A', 'A', null),
('c1-q29', 1, 29, null, 'The managerial role that changes the most between middle and top managers is ________.', '["planning", "organizing", "controlling", "leading"]'::jsonb, 'D', 'D', null),
('c1-q30', 1, 30, null, 'The role of ________ is more important for managers of small organizations than for managers working in large corporations.', '["disseminator", "spokesperson", "entrepreneur", "resource allocator"]'::jsonb, 'B', 'B', null),
('c1-q31', 1, 31, null, 'In a small organization, which one of the following is NOT likely to be true?', '["Planning is not likely to be an orchestrated ritual.", "Relationships are more likely to be informal.", "Workers are likely to be observed by computerized monitoring systems.", "The design of the organization is likely to be less structured and complex."]'::jsonb, 'C', 'C', null),
('c1-q32', 1, 32, null, 'Unlike the manager of a small business, the most important concerns of a manager in a large organization are focused ________.', '["externally, particularly on entrepreneurial tasks", "internally, particularly on the allocation of resources", "on setting goals", "on planning ways to improve organizational structure"]'::jsonb, 'B', 'B', null),
('c1-q33', 1, 33, null, 'Which one of the following statements regarding management and national culture is the most correct?', '["The basic principles of management are universal.", "Research shows that managerial practices across all countries are not consistent.", "There are major differences in the way that most English speaking countries view management.", "The route of the differences between how countries practice management is based on their economic principles solely."]'::jsonb, 'B', 'B', null),
('c1-q34', 1, 34, null, 'Companies that are well managed can prosper during difficult economic times by depending on ________.', '["government bailouts", "filing for bankruptcy", "raising prices", "a loyal customer base"]'::jsonb, 'D', 'D', null),
('c1-q35', 1, 35, null, 'Designing a series of interview questions to provide information about possible customers for a company would primarily require ________.', '["technical skills", "interpersonal skills", "conceptual skills", "political skills"]'::jsonb, 'C', 'C', null),
('c1-q36', 1, 36, null, 'Which level of management would be more concerned with designing the overall structure of an organization?', '["middle management", "supervisory management", "top management", "first line management"]'::jsonb, 'C', 'A', 'CORRECTED: A (middle management) is circled on the sheet. Designing the overall structure of the whole organization is a top-management task (top managers make organization-wide decisions and set plans/structure). Please double-check with your instructor.'),
('c1-q37', 1, 37, null, 'Technical skills might include ________.', '["excellent verbal skills", "proficiency in computer programming", "exceptional writing ability", "decision-making ability"]'::jsonb, 'B', 'B', null),
('c1-q38', 1, 38, null, 'The primary job of a manager is to ________.', '["make decisions that help an organization grow", "tackle tasks that are too difficult for nonmanagerial employees", "coordinate between organization leaders and ordinary employees", "direct and oversee the work of others"]'::jsonb, 'D', 'D', null),
('c1-q39', 1, 39, null, 'Which one of the following is NOT a characteristic of a small business?', '["has more formal managers than a large business", "has about 200 employees", "is not a \"player\" with impact within its industry", "has a relatively small market share of its product"]'::jsonb, 'A', 'A', null),
('c1-q40', 1, 40, null, 'Almost all managerial tasks involve ________.', '["decision making", "technical skills", "long-term planning", "superb political skills"]'::jsonb, 'A', 'A', null)
insert into public.open_questions (id, chapter, num, question, model_answer) values
('c1-o1', 1, 1, 'In a short essay, list and explain the four basic functions of management.', 'The four basic functions of management (Fayol, condensed) are planning, organizing, leading, and controlling.
